// tetris_rules.c - generated by split_c.py from tetris.c
#include "tetris_priv.h"



//*****************************************************************************
// 3. BOARD RULES (no drawing in this section)
//*****************************************************************************

int16_t tet_NextFromBag(void)
{
    int16_t i, j, t;

    if(tet_bagIdx >= 7)
    {
        for(i = 0; i < 7; i++) tet_bag[i] = i;

        // Fisher-Yates shuffle
        for(i = 6; i > 0; i--)
        {
            j = (int16_t)(Rand16() % (uint16_t)(i + 1));
            t = tet_bag[i];
            tet_bag[i] = tet_bag[j];
            tet_bag[j] = t;
        }
        tet_bagIdx = 0;
    }
    return tet_bag[tet_bagIdx++];
}


// Can piece (type, rot) sit with its 4x4 box at (px, py)?
// Cells ABOVE the board (row < 0) are allowed (pieces spawn partly above).
bool tet_Fits(int16_t type, int16_t rot, int16_t px, int16_t py)
{
    uint16_t mask = tet_shapes[type][rot];
    int16_t r, c, br, bc;

    for(r = 0; r < 4; r++)
    {
        for(c = 0; c < 4; c++)
        {
            if(mask & (0x8000U >> (r * 4 + c)))
            {
                br = py + r;
                bc = px + c;

                if(bc < 0 || bc >= TETRIS_BOARD_W || br >= TETRIS_BOARD_H) return false;
                if(br >= 0 && tet_board[br][bc]) return false;
            }
        }
    }
    return true;
}


// Stamp a piece into the board permanently (called when it lands).
void tet_PlaceOnBoard(int16_t type, int16_t rot, int16_t px, int16_t py)
{
    uint16_t mask = tet_shapes[type][rot];
    int16_t r, c, br, bc;

    for(r = 0; r < 4; r++)
    {
        for(c = 0; c < 4; c++)
        {
            if(mask & (0x8000U >> (r * 4 + c)))
            {
                br = py + r;
                bc = px + c;
                if(br >= 0 && br < TETRIS_BOARD_H && bc >= 0 && bc < TETRIS_BOARD_W)
                    tet_board[br][bc] = (uint16_t)(type + 1);
            }
        }
    }
}


// Remove every full row, sliding everything above it down. Returns 0..4.
int16_t tet_ClearFullRows(void)
{
    int16_t r, c, k, full, cleared = 0;

    r = TETRIS_BOARD_H - 1;
    while(r >= 0)
    {
        full = 1;
        for(c = 0; c < TETRIS_BOARD_W; c++)
        {
            if(!tet_board[r][c]) { full = 0; break; }
        }

        if(full)
        {
            for(k = r; k > 0; k--)
                for(c = 0; c < TETRIS_BOARD_W; c++) tet_board[k][c] = tet_board[k - 1][c];
            for(c = 0; c < TETRIS_BOARD_W; c++) tet_board[0][c] = 0;
            cleared++;
            // Do NOT move r: the row that slid into r might also be full.
        }
        else
        {
            r--;
        }
    }
    return cleared;
}


// Which rows are full RIGHT NOW? Returns a bitmask (bit r = row r) and the
// count. Does NOT change the board: the flash plays first, ClearFullRows()
// runs afterwards.  (1UL: the C28x int is only 16 bits, rows go up to 19.)
uint32_t tet_FindFullRows(int16_t *count)
{
    uint32_t mask = 0;
    int16_t  r, c, n = 0;

    for(r = 0; r < TETRIS_BOARD_H; r++)
    {
        for(c = 0; c < TETRIS_BOARD_W; c++)
            if(!tet_board[r][c]) break;

        if(c == TETRIS_BOARD_W)
        {
            mask |= 1UL << r;
            n++;
        }
    }
    *count = n;
    return mask;
}
